    "description": "窓口の係員と乗客（自分）の対話。チョイバルサン行き長距離バス、明日朝8時発、運賃30,000トグログ、夕方18時着、カード購入。",
    "examinerPromptMn": "Та тасалбар авах газарт очихдоо, ажилтантай юу гэж ярих вэ?",
    "examinerPromptJa": "チケット売り場に行く時、係員とどのように話しますか？",
